-- 0) La columna la crea el API nuevo al arrancar (migrate deploy).
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='users' AND column_name='mustChangePassword') THEN
    RAISE EXCEPTION 'Falta users.mustChangePassword: arranca primero el API nuevo (migrate deploy).';
  END IF;
END $$;

-- 0b) Si ya se aplicó, no se vuelve a correr (reiniciaría contraseñas).
DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM audit_logs WHERE action = 'USER_SYNC_CREATED' AND metadata->>'origen' = 'cruce reloj';
